function formatMoney(price){return new Intl.NumberFormat(selectedCurrency==='INR'?'en-IN':selectedCurrency==='UGX'?'en-UG':'en-US',{style:'currency',currency:selectedCurrency,maximumFractionDigits:selectedCurrency==='USD'?2:0}).format(price)}
function quoteLabel(service){let price=service.prices?.[selectedCurrency];if(price==null&&service.startPrices?.INR!=null)price=service.startPrices.INR*inrExchangeRates[selectedCurrency];if(price==null)return 'Request a quote';return `From ${formatMoney(price)}`}
function packagePriceLabel(option){const price=option?.prices?.[selectedCurrency];return price==null?'Request a quote':formatMoney(price)}
function updateBookingPrice(form){const output=form?.querySelector('[data-booking-price]');if(!output)return;const service=services.find(item=>item.id===form.querySelector('[data-booking-service]')?.value);const subservice=service?.subservices.find(item=>item.name===form.querySelector('[data-booking-subservice]')?.value);const packageName=form.querySelector('[data-booking-package]')?.value;const option=subservice?.packages.find(item=>item.name===packageName);output.textContent=option?`Selected package price: ${packagePriceLabel(option)}`:'Choose a service, option, and package to see the price.'}
function paymentPreference(booking){return booking.payment_method||booking.notes?.match(/Payment preference: ([^\n]+)/)?.[1]||''}
function serviceCards(){return services.map(s=>`<article class="service-card"><button class="service-card-image" data-explore-service="${s.id}" aria-label="Explore ${s.name}"><img src="${s.image}" alt="${s.name}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=1200&q=85'"><span class="service-card-index">${s.number} <b>↗</b></span></button><div class="service-card-copy"><div class="service-card-icon">${s.icon}</div><span class="service-card-discipline">${s.number} / ${s.discipline}</span><h3>${s.name}</h3><p>${s.description}</p><div class="service-card-footer"><strong data-price-for="${s.id}">${quoteLabel(s)}</strong><button class="service-explore" data-explore-service="${s.id}">Explore service <span>↗</span></button></div></div></article>`).join('')}
